import { ChromaClient } from "chromadb";

// after:  chroma run --path ./db
const client = new ChromaClient();
const notes = await client.getOrCreateCollection({ name: "notes" });
await notes.add({ ids: ["1", "2"], documents: ["Cats purr when happy.", "GPUs speed up training."] });
console.log(await notes.query({ queryTexts: ["why do kittens purr"], nResults: 1 }));
